// Azure Function — event-driven, scales to zero, pay-per-execution
public class OrderProcessor
{
    [Function("ProcessOrderQueue")]
    public async Task Run(
        [QueueTrigger("orders-queue")] string orderJson,
        FunctionContext context)
    {
        var logger = context.GetLogger("ProcessOrderQueue");
        var order = JsonSerializer.Deserialize<Order>(orderJson);
        logger.LogInformation($"Processing order {order.Id}");
        // ... business logic, no server to keep warm between triggers
    }
}

// App Service — always-on ASP.NET Core Web API, steady traffic
// Program.cs — a normal minimal API, deployed once, running continuously
var app = WebApplication.Create();
app.MapGet("/orders/{id}", (int id) => Results.Ok(new { id }));
app.Run(); // stays warm; scale by adding instances in App Service Plan

// Service Bus — reliable command, must not be lost
await using var client = new ServiceBusClient(connectionString);
ServiceBusSender sender = client.CreateSender("orders-queue");
var message = new ServiceBusMessage(JsonSerializer.Serialize(order))
{
    SessionId = order.CustomerId.ToString(), // FIFO per customer
    MessageId = order.Id.ToString()          // enables duplicate detection
};
await sender.SendMessageAsync(message);

// Event Grid — lightweight reactive notification (fire-and-react)
[Function("OnBlobUploaded")]
public void Run([EventGridTrigger] EventGridEvent evt)
{
    // reacts to "a blob was uploaded" near-instantly; no durability guarantee
    _logger.LogInformation($"Event: {evt.EventType} on {evt.Subject}");
}

// Event Hub — massive telemetry stream, consumer controls offset
await using var producer = new EventHubProducerClient(connString, "telemetry-hub");
using EventDataBatch batch = await producer.CreateBatchAsync();
batch.TryAdd(new EventData(Encoding.UTF8.GetBytes(sensorReadingJson)));
await producer.SendAsync(batch);

