public class OrderServiceTests
{
    [Fact]
    public void PlaceOrder_WhenValid_SendsNotification()
    {
        // ARRANGE
        var mockNotifier = new Mock<INotificationService>();
        var mockRepo = new Mock<IOrderRepository>();
        var service = new OrderService(mockRepo.Object, mockNotifier.Object);
        var order = new Order { Id = 1, CustomerEmail = "a@b.com" };

        // ACT
        service.PlaceOrder(order);

        // ASSERT
        mockRepo.Verify(r => r.Save(order), Times.Once);
        mockNotifier.Verify(n => n.Send("a@b.com", It.IsAny<string>()), Times.Once);
    }

    [Theory]
    [InlineData(0, false)]
    [InlineData(-100, false)]
    [InlineData(500, true)]
    public void ValidateAmount_ReturnsExpected(decimal amount, bool expected)
        => Assert.Equal(expected, new OrderValidator().IsValidAmount(amount));

    [Fact]
    public void Withdraw_WhenInsufficientFunds_Throws()
        => Assert.Throws<InvalidOperationException>(() => new BankAccount(100).Withdraw(500));
}

