db.Users.Where(u => u.Name == name).ToList();            // ✔ EF Core parameterizes automatically

// SECURITY — missing server-side authorization check
[HttpGet("orders/{id}")]
public IActionResult GetOrder(int id)
{
    var order = _repo.GetById(id);
    if (order.UserId != CurrentUserId) return Forbid(); // ✔ must check ownership server-side
    return Ok(order);
}

// ERROR HANDLING — throw; preserves the stack trace, throw ex; resets it
try { DoWork(); }
catch (Exception ex)
{
    _logger.LogError(ex, "DoWork failed");
    throw;      // ✔ preserves original stack trace
    // throw ex;  ✖ resets the stack trace, hides where it really failed
}

// PERFORMANCE — N+1 query a reviewer should flag
