    order.Customer = db.Customers.Find(order.CustomerId); // ✖ one query per order
var customers = db.Customers.Where(c => ids.Contains(c.Id)).ToList(); // ✔ one query total

// SQL INJECTION
var sql = $"SELECT * FROM Users WHERE Name = '{name}'"; // ✖ VULNERABLE
db.Users.Where(u => u.Name == name).ToList();            // ✔ EF Core parameterizes
cmd.Parameters.AddWithValue("@Name", name);               // ✔ ADO.NET parameterized

// PASSWORDS — hash + salt, never plaintext/MD5/SHA1
var hasher = new PasswordHasher<User>();
user.PasswordHash = hasher.HashPassword(user, plainPassword); // ✔ ASP.NET Core Identity (PBKDF2)

// BROKEN ACCESS CONTROL — always verify ownership server-side
[HttpDelete("orders/{id}")]
[Authorize]
public IActionResult DeleteOrder(int id)
{
    var order = _repo.GetById(id);
    if (order.UserId != CurrentUserId) return Forbid(); // ✔ never trust a hidden UI button
    _repo.Delete(order);
    return NoContent();
}

// OVER-POSTING — bind to a DTO, never the entity directly
public class UpdateProfileDto { public string Name { get; set; } public string Email { get; set; } } // no IsAdmin field
[HttpPut("profile")]
public IActionResult UpdateProfile(UpdateProfileDto dto) // ✔ client can't set IsAdmin=true
{
    var user = _repo.GetById(CurrentUserId);
    user.Name = dto.Name; user.Email = dto.Email;
    return Ok();
}
